"use strict";
// SECURITY & INTEGRITY AUDIT round — duplicate-submission protection.
//
// A save request (POST/PATCH/DELETE under /api/) may carry an
// `Idempotency-Key` header: one random id per form submission, generated by
// the browser when the form opens. If the same request is sent again — a
// double click, a network retry, a resend after a timeout — the server does
// NOT run it again; it answers with the response of the first one. A second
// copy that arrives while the first is still running waits for it and gets
// the same answer. So one payment, exchange, transfer, loan or cash movement
// can never be posted twice by a repeated submission.
//
// Scope: a key only ever matches the same signed-in session (a hash of the
// Authorization header — never the token itself), the same method and the
// same path. Another user, another company workspace or another endpoint can
// never receive someone else's stored answer. Requests without the header
// behave exactly as before.
//
// Only answers below 500 are kept (a success, or a validation refusal that a
// retry would just get again); a server error is forgotten so the same
// submission can be retried. Entries live in memory for 24 hours, at most
// MAX_ENTRIES at a time — enough to cover any retry of one submission; a
// server restart clears them.
const crypto = require("crypto");

const TTL_MS = 24 * 60 * 60 * 1000;
const MAX_ENTRIES = 20000;
const KEY_RE = /^[A-Za-z0-9_-]{8,100}$/;
const entries = new Map(); // scope -> { state: "pending"|"done", at, status, headers, body, waiters: [] }

function scopeFor(req, pathname) {
  if (!["POST", "PATCH", "DELETE", "PUT"].includes(req.method)) return null;
  const key = String(req.headers["idempotency-key"] || "").trim();
  if (!key || !KEY_RE.test(key)) return null;
  const auth = String(req.headers.authorization || "");
  if (!auth) return null; // nothing to scope it to; the route will refuse anyway
  const who = crypto.createHash("sha256").update(auth).digest("hex");
  return `${who}|${req.method}|${pathname}|${key}`;
}

function prune(now) {
  for (const [k, e] of entries) {
    if (e.state === "done" && now - e.at > TTL_MS) entries.delete(k);
  }
  while (entries.size > MAX_ENTRIES) {
    const oldest = entries.keys().next().value;
    if (entries.get(oldest).state === "pending") break;
    entries.delete(oldest);
  }
}

function replay(res, e) {
  if (res.headersSent) return;
  const headers = { ...e.headers, "Idempotent-Replay": "true" };
  res.writeHead(e.status, headers);
  res.end(e.body);
}

// Returns true when the request has been answered (or will be, once the
// first copy finishes) and the handler must NOT run.
function begin(scope, res) {
  const now = Date.now();
  prune(now);
  const e = entries.get(scope);
  if (e && e.state === "done") { replay(res, e); return true; }
  if (e && e.state === "pending") { e.waiters.push(res); return true; }
  entries.set(scope, { state: "pending", at: now, waiters: [] });
  capture(scope, res);
  return false;
}

// Records what the handler sends, then releases anyone waiting.
function capture(scope, res) {
  const chunks = [];
  let status = 200;
  const headers = {};
  const origWriteHead = res.writeHead.bind(res);
  const origEnd = res.end.bind(res);
  const origWrite = res.write.bind(res);
  res.writeHead = (code, a, b) => {
    status = code;
    const h = typeof a === "object" && a ? a : b;
    if (h && typeof h === "object") for (const [k, v] of Object.entries(h)) headers[k] = v;
    return origWriteHead(code, a, b);
  };
  res.write = (chunk, ...rest) => {
    if (chunk) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
    return origWrite(chunk, ...rest);
  };
  res.end = (chunk, ...rest) => {
    if (chunk && typeof chunk !== "function") chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
    const result = origEnd(chunk, ...rest);
    finish(scope, { status: res.statusCode || status, headers: { "Content-Type": res.getHeader("Content-Type") || headers["Content-Type"] || "application/json", ...pick(headers) }, body: Buffer.concat(chunks) });
    return result;
  };
  // A connection that drops before an answer must not leave the key stuck.
  res.on("close", () => {
    const e = entries.get(scope);
    if (e && e.state === "pending" && !res.writableEnded) finish(scope, null);
  });
}

function pick(h) {
  const out = {};
  for (const k of Object.keys(h)) if (/^content-(type|disposition)$/i.test(k)) out[k] = h[k];
  return out;
}

function finish(scope, answer) {
  const e = entries.get(scope);
  if (!e || e.state !== "pending") return;
  const waiters = e.waiters;
  if (answer && answer.status < 500) {
    entries.set(scope, { state: "done", at: Date.now(), status: answer.status, headers: answer.headers, body: answer.body, waiters: [] });
    for (const w of waiters) replay(w, entries.get(scope));
  } else {
    entries.delete(scope);
    for (const w of waiters) {
      if (answer) replay(w, { status: answer.status, headers: answer.headers, body: answer.body });
      else if (!w.headersSent) { w.writeHead(409, { "Content-Type": "application/json" }); w.end(JSON.stringify({ error: "The first copy of this request did not finish. Please try again." })); }
    }
  }
}

function _reset() { entries.clear(); }

module.exports = { scopeFor, begin, _reset };
